INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('ecdae106-9428-40e0-b357-4b6302161634', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$131. óra: Az oszthatóságról tanultak összefoglalása$q$, $q$Év végi ismétlés: oszthatósági szabályok, prímek, lkkt és lnko.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Év végi ismétlés$q$, $q$[{"id": "74407f63-1bf8-4510-af40-194e2a8e4716", "text": "Osztható-e a 435 5-tel és 3-mal is (azaz 15-tel)?", "type": "true-false", "options": [{"id": "299b540f-a0f0-4b46-a9f7-99e52227503e", "text": "Igaz (5-re végződik és 4+3+5=12)", "isCorrect": true}, {"id": "14f58b72-5653-4d53-a7f1-4730258f858c", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "7dcde894-72ee-4e14-a7dc-ce4ec8cf7805", "text": "Osztható-e a 612 4-gyel?", "type": "true-false", "options": [{"id": "ad3350d7-9f4d-483d-97ed-bda7cff40cee", "text": "Igaz (12 osztható 4-gyel)", "isCorrect": true}, {"id": "276aaf6b-d7cf-4288-a5b4-3d147110c60d", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "cc9be554-e2f7-4d86-b620-10217bfd3432", "text": "Mennyi lkkt(6, 8)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "24"}, {"id": "c70d3df8-713b-43ed-a14c-3633d2ad1671", "text": "Mennyi lnko(12, 18)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "1dd9a106-8460-48a9-82c4-8a776396cabe", "text": "Melyik a legkisebbkétjegyű prímszám?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "11"}, {"id": "f9d09a5e-314f-4504-8dc3-bf41e045581e", "text": "A 2 az egyetlen páros prímszám.", "type": "true-false", "options": [{"id": "d2e10547-f642-4f3a-a6a0-763acb7e74ec", "text": "Igaz", "isCorrect": true}, {"id": "b0f69435-ef47-425f-862c-65c1d4d74097", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "a5a8f40b-5ebb-476a-9dbd-62c762e5a24d", "text": "Melyik szám osztható 9-cel?", "type": "multiple-choice", "options": [{"id": "e0e41758-92c6-4ae2-a03c-3d06373ee71a", "text": "819 (8+1+9=18)", "isCorrect": true}, {"id": "e29e008e-79dd-4c01-9cad-4d9f7b3c3048", "text": "815", "isCorrect": false}, {"id": "f1144959-7104-46cb-b0d0-5cdf5b2990ac", "text": "812", "isCorrect": false}, {"id": "3faabeac-4878-405c-b78a-26049006d428", "text": "811", "isCorrect": false}], "timeLimit": 15}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('b2d194b2-a284-42c9-85f1-4fe24ad75ec4', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$132. óra: A törtekről tanultak összefoglalása, vegyes feladatok$q$, $q$Év végi ismétlés: közönséges és tizedes törtek műveletei.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Év végi ismétlés$q$, $q$[{"id": "75762ff0-c6a4-47a1-8318-5acc328d8774", "text": "Mennyi 3/4 + 1/2? (3/4 + 2/4)", "type": "multiple-choice", "options": [{"id": "3bfbaf5e-41b8-4df7-93a8-046d7b291b0c", "text": "5/4 (1 egész 1/4)", "isCorrect": true}, {"id": "79990e96-c021-4a6c-bbae-db4a93eb753b", "text": "4/6", "isCorrect": false}, {"id": "fa75e800-2f67-4599-81a0-23f65fb43b35", "text": "4/4", "isCorrect": false}, {"id": "d0924b26-5e9d-4bcc-a028-9f853c01e803", "text": "3/8", "isCorrect": false}], "timeLimit": 15}, {"id": "a7e7d1dd-9553-4145-873a-d0ccf6875710", "text": "Mennyi 2/3 * 3/5?", "type": "multiple-choice", "options": [{"id": "678bcb8b-d158-48ce-ad8e-f87d4a3d0ac6", "text": "2/5", "isCorrect": true}, {"id": "c553e6f6-7e95-4f08-b029-5f32145e9a90", "text": "6/15", "isCorrect": false}, {"id": "32ab5c0a-6739-45c5-9f4a-b6a50e274caf", "text": "5/8", "isCorrect": false}, {"id": "55603184-6cee-4183-8357-698a1373fdbc", "text": "6/8", "isCorrect": false}], "timeLimit": 15}, {"id": "3b504bb5-4db8-49a3-ac36-bd9f219ef2da", "text": "Mennyi 1/2 : 1/4?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}, {"id": "fc765430-bd75-4d9e-a960-2c6ba01d5ac2", "text": "Mennyi 2,5 * 0,4?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}, {"id": "f38f96a8-d369-48e6-8d1c-d20e573abfad", "text": "Mennyi 4,8 : 0,6?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "8"}, {"id": "a38a0526-0dad-4e1e-bd45-f2bf6ff9b6e8", "text": "A 0,75 megegyezik a 3/4 törttel.", "type": "true-false", "options": [{"id": "eefc9d41-60f9-44db-88e3-3d91ad120f9e", "text": "Igaz", "isCorrect": true}, {"id": "2eda53bf-5acb-4a68-b434-12660d94b271", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "295ef4c1-324f-441f-beb3-fed754ef37bf", "text": "Mennyi 80-nak a 3/4 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "60"}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('d77f50fa-6ccf-4cb6-950d-1faf46262fb5', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$133. óra: A geometriai ismeretek összefoglalása, vegyes feladatok$q$, $q$Év végi ismétlés: szögek, alakzatok, tengelyes tükrözés.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Év végi ismétlés$q$, $q$[{"id": "fd463d2a-0b85-4318-b0ee-5750d5ed3fa1", "text": "Mennyi a háromszög belső szögeinek összege?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "180"}, {"id": "721b1d1e-abc1-47e3-b81e-c98d7f0cafc5", "text": "Mennyi a négyszög belső szögeinek összege?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "360"}, {"id": "8804f08e-851b-4f76-b1e4-8a0edbb61f43", "text": "Hány szimmetriatengelye van a négyzetnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "aeaeb148-a92c-4a95-983f-6ccceeb9d39b", "text": "Ha a kör sugara 6 cm, mekkora az átmérője? (cm-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "12"}, {"id": "7ce4cb4f-c262-4fae-893f-479cd3371500", "text": "A tengelyes tükrözés távolságtartó transzformáció.", "type": "true-false", "options": [{"id": "18dd75b7-752a-4c99-8ef2-c1c25c7f2d53", "text": "Igaz", "isCorrect": true}, {"id": "54ef83b6-b882-47b9-89dd-f1f4e214663d", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "bd7d7f2b-d438-421a-8270-17705c577d7d", "text": "Hány fokos szöget zár be a szakaszfelező merőleges a szakasszal?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "90"}, {"id": "45994612-a63d-49fd-9fff-2e582a7ba055", "text": "Milyen szög a 90°-os szög?", "type": "multiple-choice", "options": [{"id": "7cba1398-457f-4650-8dee-b76e27dda731", "text": "Derékszög", "isCorrect": true}, {"id": "60526c04-f8f0-4fd3-8053-ff017e5f13be", "text": "Hegyesszög", "isCorrect": false}, {"id": "24a638e9-4dc8-4add-8697-885e4f04aa44", "text": "Tompaszög", "isCorrect": false}, {"id": "b6ad9fd4-64bc-421b-8300-8dc03ad2aa4b", "text": "Egyenesszög", "isCorrect": false}], "timeLimit": 15}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('a5b665fb-e628-4dee-9ca9-06f6c0d6176c', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$134. óra: Arányosság, százalék, szöveges feladatok$q$, $q$Év végi ismétlés: egyenes arányosság, százalékszámítás, nyitott mondatok.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Év végi ismétlés$q$, $q$[{"id": "64a508c1-b465-4ac3-88f5-a978389efcfd", "text": "Ossz el 500 Ft-ot 2 : 3 arányban! Hány Ft a kisebbik rész?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "200"}, {"id": "33fbeb06-da2c-486c-8a4c-8a693903a913", "text": "Ha 3 kg narancs 1200 Ft, mennyibe kerül 7 kg narancs?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2800"}, {"id": "9b7e37bb-8edf-4de5-af0a-f5f5b72277e7", "text": "Mennyi 4000 Ft-nak a 20%-a?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "800"}, {"id": "082d63f0-2e77-4ada-86c4-195a76584ca3", "text": "Melyik szám teszi igazzá: 3 * x + 5 = 26? (21/3)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "7"}, {"id": "cfe71b1c-dd60-464c-a4d8-66eb62fb21e6", "text": "Gondoltam egy számot, elosztottam 4-gyel, hozzáadtam 6-ot, 11-et kaptam. Mi a szám?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "664d3824-6ae0-4d33-b678-5f260eb8da0e", "text": "Az egyenes arányosság grafikonja az origóból induló félegyenes.", "type": "true-false", "options": [{"id": "68f9d2ed-9d6b-4284-90b7-cfe3ec878503", "text": "Igaz", "isCorrect": true}, {"id": "311c4ee8-5dea-45a0-a984-e67bc69c4fd9", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "a439fafb-9d01-4b25-bbbf-a47008a528ac", "text": "Hány százalék felel meg a 4/5 törtszám teljes értékének?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "80"}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('8845caca-bf84-4fc7-be79-d0b4191e1d59', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$135. óra: A hosszúság, a kerület, a terület és a térfogat fogalmával kapcsolatos feladatok$q$, $q$Év végi ismétlés: mérések, kerület, terület, felszín, térfogat.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Év végi ismétlés$q$, $q$[{"id": "7800c35e-ba43-4c7a-914d-5ca92b313798", "text": "Mennyi a 6 cm és 5 cm oldalú téglalap területe? (cm²-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}, {"id": "cffc33fc-b86c-43d4-a2d5-f7a401264ad8", "text": "Mennyi a 6 cm és 5 cm oldalú téglalap kerülete? (cm-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "22"}, {"id": "72004473-79b5-4490-90f7-546a2830bfb0", "text": "Mennyi a 4 cm élű kocka felszíne? (6 * 16)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "96"}, {"id": "15f571d7-19f8-49b6-94a1-fe71f9e7f33a", "text": "Mennyi a 4 cm élű kocka térfogata? (4 * 4 * 4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "64"}, {"id": "7d7f6a4a-3b8f-4633-b4e1-6128a1f18fa3", "text": "1 liter víz térfogata 1 dm³.", "type": "true-false", "options": [{"id": "bddcf9e9-40f6-42f9-a7bb-3bd8921d8ea7", "text": "Igaz", "isCorrect": true}, {"id": "a3d16b2b-ed31-4aa6-92fb-f0c1845f22b0", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "fe2de3a1-1371-470a-826f-cb0739b51f0f", "text": "Hány cm³ 1 dm³?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1000"}, {"id": "4547f0bd-0ed5-4368-8aeb-846eb7763998", "text": "Hány mm² 1 cm²?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "100"}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('15e7b1d8-f048-46ff-846a-9624f5f94ee9', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$136. óra: Az éves munka értékelése$q$, $q$Az 6. osztályos matematika törzsanyag sikeres teljesítésének záró értékelése.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Év végi ismétlés$q$, $q$[{"id": "dded9990-75e0-40ab-92c3-e67fed97cddc", "text": "Mely főbb témaköröket dolgoztuk fel a 6. osztályos matematika tananyagban?", "type": "multiple-choice", "options": [{"id": "0bd85d97-c9ca-4564-bda1-d95204beb4af", "text": "Egész számok, oszthatóság, törtek, geometria, arány és százalék, kerület-terület-felszín-térfogat, statisztika, pénzügyek", "isCorrect": true}, {"id": "16c7cd7b-60ca-4f9f-9319-476e1d556747", "text": "Kizárólag geometria", "isCorrect": false}, {"id": "4fd6b0e2-359d-44dd-8764-4b9c50ac0d0a", "text": "Kizárólag rajzolás", "isCorrect": false}, {"id": "0cc66876-76dd-4a1c-bd13-3aefdc664a51", "text": "Csak az 1. osztályos ismétlés", "isCorrect": false}], "timeLimit": 15}, {"id": "af13c2b2-f7d4-417e-aa9f-7d6ec4755cc3", "text": "A szorgalmas felkészülés és a rendszerezett gyakorlás a matematikai tudás alapja.", "type": "true-false", "options": [{"id": "0ec91c6a-02b2-4a36-9ba2-76b424ef6a2c", "text": "Igaz", "isCorrect": true}, {"id": "d44cec56-07fa-4d78-8b91-e6b1f48d62e7", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "0996f2b9-49fa-4bd1-b8f0-89db24f1d6b3", "text": "Hány órából állt a 6. osztályos teljes matematika tananyag?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "136"}, {"id": "e1453af4-ad1c-457a-8d55-e3c0ddd74f40", "text": "A megszerzett matematikai tudás segít a mindennapi pénzügyekben és a döntéshozatalban.", "type": "true-false", "options": [{"id": "fbc894a8-30cf-48b9-8a3b-2e5df8b32a2d", "text": "Igaz", "isCorrect": true}, {"id": "6f181693-3db4-4b5b-a2ee-371f60b77b98", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "91dc04b3-09b3-4595-922c-c3c817105c87", "text": "Gratulálunk a 6. osztályos matematika tananyag sikeres teljesítéséhez!", "type": "true-false", "options": [{"id": "d1e7d4f7-ef5c-48e1-ae0f-cea5de6ebcca", "text": "Igaz", "isCorrect": true}, {"id": "34f71fab-4eec-4e6e-aac8-d77ac0f97991", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "0544611c-3311-4e01-8388-a2ee69c401dd", "text": "A 7. osztályban az itt megszerzett alapokra (pl. oszthatóság, törtek, százalék, geometria) építünk tovább.", "type": "true-false", "options": [{"id": "4e9dd18c-95eb-4fbe-9176-7410e7c74239", "text": "Igaz", "isCorrect": true}, {"id": "c91ca369-e1ad-44f6-9ba0-08bbbaf4f4ea", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "e84f1428-0673-4c3e-8489-41854201924f", "text": "Melyik volt a kedvenc témaköröd ebben a tanévben?", "type": "multiple-choice", "options": [{"id": "a466a7bc-a708-4c1f-ae7d-b822115c8b5a", "text": "Mindegyik témakör hasznos és érdekes volt!", "isCorrect": true}, {"id": "b9fbf3f4-a2d8-4d9a-b954-1e03c2448db1", "text": "Egész számok és oszthatóság", "isCorrect": false}, {"id": "c918916c-05f4-42cd-b418-11eefd9822d7", "text": "Geometria és tengelyes tükrözés", "isCorrect": false}, {"id": "571ac18c-8e76-4b00-9cf6-487b75fc270c", "text": "Arányosság és százalékszámítás", "isCorrect": false}], "timeLimit": 15}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;